import {gameById} from './catalog.js';
export const HISTORY_KEY='practice-studio.history.v1';
export function validResult(r){return !!r&&typeof r.id==='string'&&!!gameById(r.gameId)&&Number.isInteger(r.version)&&r.version>0&&['learn','timed'].includes(r.mode)&&['easy','standard','hard'].includes(r.difficulty)&&Number.isFinite(r.timestamp)&&Number.isFinite(r.elapsed)&&r.elapsed>=0&&Number.isInteger(r.attempts)&&r.attempts>=0&&Number.isInteger(r.correct)&&r.correct>=0&&r.correct<=r.attempts&&typeof r.scored==='boolean'&&r.metrics!==null&&typeof r.metrics==='object'&&!Array.isArray(r.metrics)&&validMetrics(r.metrics);}
function validMetrics(m){if(m.responses!==undefined&&(!Array.isArray(m.responses)||!m.responses.every(x=>x&&typeof x.prompt==='string'&&typeof x.choice==='string'&&typeof x.trait==='string'&&(x.value===undefined||(Number.isInteger(x.value)&&x.value>=1&&x.value<=5)))))return false;return ['span','nBack','hits','misses','falseAlarms','correctHolds','reactionMs'].every(k=>m[k]===undefined||m[k]===null||(Number.isFinite(m[k])&&m[k]>=0));}
export function loadHistory(storage){try{const raw=storage.getItem(HISTORY_KEY);if(!raw)return {records:[],warning:''};const parsed=JSON.parse(raw);if(!Array.isArray(parsed))throw Error();const records=parsed.filter(validResult);return {records,warning:records.length!==parsed.length?'Some unreadable sessions were skipped. Export your history before clearing it.':''};}catch{return {records:[],warning:'Saved history could not be read. You can still practice; export any results you want to keep.'};}}
export function saveResult(storage,result){try{if(!validResult(result))throw Error();const {records,warning}=loadHistory(storage);if(warning) return {saved:false,warning:'Your result is available here, but existing history could not be read. Export this result to keep it.'};storage.setItem(HISTORY_KEY,JSON.stringify([...records.filter(r=>r.id!==result.id),result]));return {saved:true,warning:''};}catch{return {saved:false,warning:'This browser could not save your session. Export this result to keep it.'};}}
export const compatibleHistory=(history,result)=>history.filter(r=>r.id!==result.id&&r.gameId===result.gameId&&r.version===result.version&&r.mode===result.mode&&r.difficulty===result.difficulty);
export function priorHistory(history,result){const index=history.findIndex(r=>r.id===result.id);return compatibleHistory(index>=0?history.slice(0,index):history.filter(r=>r.timestamp<=result.timestamp),result).filter(r=>!r.scored||r.attempts>0);}
export function summarize(records){const scored=records.filter(r=>r.scored&&r.attempts>0);const attempts=scored.reduce((n,r)=>n+r.attempts,0),correct=scored.reduce((n,r)=>n+r.correct,0);const rate=r=>r.elapsed>0?r.correct*60/r.elapsed:0;const first=scored[0],last=scored.at(-1);return {sessions:records.length,accuracy:attempts?Math.round(correct/attempts*100):null,best:scored.length?Math.max(...scored.map(rate)):null,baseline:first?rate(first):null,repeat:scored.length>1,improvement:first&&rate(first)>0&&scored.length>1?Math.round((rate(last)-rate(first))/rate(first)*100):null};}
export function browserStorage(){try{return window.localStorage;}catch{return {getItem(){throw Error('Storage unavailable')},setItem(){throw Error('Storage unavailable')},removeItem(){throw Error('Storage unavailable')}};}}
